// this was written - see `contracts::sync`.
pub(crate) fn loop_candidates(arena: &mut TermArena, record: &LoopRecord, proved: &mut impl FnMut(&TermArena, &[i64], i64) -> bool, asked: &mut Vec<i64>) -> Vec<(i64, String)> {
    let mut found: Vec<(i64, String)> = vec![];
    let start = record.start;
    let mut steady: Vec<(String, i64)> = vec![];
    for (name, deltas) in record.steps.iter() {
        if deltas.is_empty() { continue; }
        let k = *nikaia_std::index::get(&deltas, 0);
        let mut one = true;
        for d in deltas.iter() {
            let d = nikaia_std::num::value(d);
            if d != k { one = false; }
        }
        if one {
            steady.push((nikaia_std::block::Text::from(name.to_string()), k));
            continue;
        }
        let here = arena.var(name);
        let before = arena.var(&loop_before_name(name, start));
        if deltas.iter().copied().all(|d| { d >= 0 }) { found.push((arena.ge(here, before), String::from("closed forms"))); } else if deltas.iter().copied().all(|d| { d <= 0 }) { found.push((arena.le(here, before), String::from("closed forms"))); }
    }
    for (name, k) in steady.iter() {
        let k = nikaia_std::num::value(k);
        let here = arena.var(name);
        let before = arena.var(&loop_before_name(name, start));
        if k == 0 { found.push((arena.equal(here, before), String::from("closed forms"))); } else if k > 0 { found.push((arena.ge(here, before), String::from("closed forms"))); } else { found.push((arena.le(here, before), String::from("closed forms"))); }
    }
    for i in 0..steady.len() as i64 {
        for j in unsafe { nikaia_std::proven::add::<i64>(i, 1) }..steady.len() as i64 {
            let (x, kx) = unsafe { nikaia_std::proven::read(&steady, (i) as usize) }; let kx = nikaia_std::num::value(kx);
            let (y, ky) = unsafe { nikaia_std::proven::read(&steady, (j) as usize) }; let ky = nikaia_std::num::value(ky);
            if kx == 0 || ky == 0 { continue; }
            let left = loop_scaled_offset(arena, record, &x, ky);
            let right = loop_scaled_offset(arena, record, &y, kx);
            found.push((arena.equal(left, right), String::from("closed forms")));
        }
    }
    let c = nikaia_std::index::or(record.problem.condition, || -1);
    if c >= 0 {
        for (name, k) in steady.iter() {
            let k = nikaia_std::num::value(k);
            let bound = match loop_bound_of(&arena, c, name, &record.problem.state) { Some(__nikaia_value) => __nikaia_value, None => continue };
            let op = nikaia_std::block::Text::from(bound.op.to_string());
            let e = bound.value;
            let here = arena.var(name);
            let before = arena.var(&loop_before_name(name, start));
            let kc = arena.int(k);
            let mut reach = arena.add(e, kc);
            let constant = arena.constant(e);
            if constant.is_some() { reach = arena.int(nikaia_std::index::or(constant, || 0) + k); }
            let mut near: Option<i64> = None;
            if k > 0 && op == "<" { near = Some(arena.lt(here, reach)); } else if k > 0 && op == "<=" { near = Some(arena.le(here, reach)); } else if k < 0 && op == ">" { near = Some(arena.gt(here, reach)); } else if k < 0 && op == ">=" { near = Some(arena.ge(here, reach)); }
            let n = match near { Some(__nikaia_value) => __nikaia_value, None => continue };
            found.push((n, String::from("closed forms")));
            let unmoved = arena.equal(here, before);
            found.push((arena.or(vec![n, unmoved]), String::from("closed forms")));
        }
    }
    for (name, deltas) in record.steps.iter() {
        let mut up = true;
        let mut down = true;
        let mut most: i64 = 0;
        let mut least: i64 = 0;
        for d in deltas.iter() {
            let d = nikaia_std::num::value(d);
            if d < 0 { up = false; }
            if d > 0 { down = false; }
            if d > most { most = d; }
            if d < least { least = d; }
        }
        if deltas.is_empty() || up && down { continue; }
        let ghost = loop_before_name(name, start);
        let known = match loop_known_value(&arena, &record.problem.fixed, &ghost) { Some(__nikaia_value) => __nikaia_value, None => continue };
        let here = arena.var(name);
        let at_start = arena.int(known);
        let limit = loop_constant_limit(&arena, c, name);
        if up {
            found.push((arena.ge(here, at_start), String::from("intervals")));
            let found_limit = match limit { Some(__nikaia_value) => __nikaia_value, None => continue };
            let op = nikaia_std::block::Text::from(found_limit.op.to_string());
            let value = found_limit.value;
            let mut top: Option<i64> = None;
            if op == "<" { top = Some(value - 1 + most); } else if op == "<=" { top = Some(value + most); }
            let t = match top { Some(__nikaia_value) => __nikaia_value, None => continue };
            let highest = if t > known { t } else { known };
            let h = arena.int(highest);
            found.push((arena.le(here, h), String::from("intervals")));
        } else {
            found.push((arena.le(here, at_start), String::from("intervals")));
            let found_limit = match limit { Some(__nikaia_value) => __nikaia_value, None => continue };
            let op = nikaia_std::block::Text::from(found_limit.op.to_string());
            let value = found_limit.value;
            let mut bottom: Option<i64> = None;
            if op == ">" { bottom = Some(value + 1 + least); } else if op == ">=" { bottom = Some(value + least); }
            let b = match bottom { Some(__nikaia_value) => __nikaia_value, None => continue };
            let lowest = if b < known { b } else { known };
            let l = arena.int(lowest);
            found.push((arena.ge(here, l), String::from("intervals")));
        }
    }
    for claim in record.asserts.iter() {
        let claim = nikaia_std::num::value(claim);
        found.push((claim, String::from("asserts")));
    }
    found.extend(loop_octagons(arena, record));
    found.extend(loop_flagged(arena, record));
    found.extend(loop_unrolled(arena, record, &steady, &mut *proved, asked));
    found
}

pub(crate) fn loop_flagged_origin() -> String { String::from("flag facts") }

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn loop_flagged(arena: &mut TermArena, record: &LoopRecord) -> Vec<(i64, String)> {
    let mut found: Vec<(i64, String)> = vec![];
    let start = record.start;
    let state = record.problem.state.copy_owned();
    let mut directions: collections::BTreeMap<String, Form> = collections::BTreeMap::new(); #[allow(clippy::redundant_locals)] let state = state;
    for (name, deltas) in record.steps.iter() {
        if deltas.is_empty() { continue; }
        let mut vars: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
        if deltas.iter().copied().all(|d| { d >= 0 }) {
            vars.insert(nikaia_std::block::Text::from(name.to_string()), -1);
            vars.insert(loop_before_name(name, start), 1);
        } else if deltas.iter().copied().all(|d| { d <= 0 }) {
            vars.insert(nikaia_std::block::Text::from(name.to_string()), 1);
            vars.insert(loop_before_name(name, start), -1);
        } else { continue; }
        directions.insert(nikaia_std::block::Text::from(name.to_string()), Form { vars, k: 0 });
    }
    let mut kept_condition: Vec<i64> = vec![];
    let c = nikaia_std::index::or(record.problem.condition, || -1);
    if c >= 0 { loop_atoms(arena, c, false, &mut kept_condition); }
    for flag in state.iter() {
        let mut rises = 0;
        let mut lowers = false;
        let mut common: collections::BTreeMap<String, Form> = collections::BTreeMap::new();
        for turn in record.turns.iter() {
            let value = match *nikaia_std::index::get(&turn.values, flag) { Some(__nikaia_value) => nikaia_std::num::value(__nikaia_value), None => continue };
            let raise = loop_raise(&arena, value, flag);
            if raise < 0 {
                lowers = true;
                break;
            }
            if raise == 0 { continue; }
            let mut said: Vec<i64> = kept_condition.copy_owned();
            for constraint in turn.constraints.iter() {
                let constraint = nikaia_std::num::value(constraint);
                loop_atoms(arena, constraint, false, &mut said);
            }
            let mut facts: Vec<Form> = vec![];
            for atom in said.iter() {
                let atom = nikaia_std::num::value(atom);
                atoms(atom, &mut |at| { arena.at(at) }, &mut facts);
            }
            let projected = loop_projected(&facts, &state, &directions);
            let mut here: collections::BTreeMap<String, Form> = collections::BTreeMap::new();
            for f in projected.iter() { here.insert(loop_form_key(f), f.clone()); }
            if rises == 0 { common = here; } else {
                let mut both: collections::BTreeMap<String, Form> = collections::BTreeMap::new();
                for (key, f) in common.iter() { if here.contains_key(key) { both.insert(nikaia_std::block::Text::from(key.to_string()), f.clone()); } }
                common = both;
            }
            rises += 1;
        }
        if lowers || rises == 0 { continue; }
        let named = arena.var(flag);
        let before = arena.var(&loop_before_name(flag, start));
        for (_, f) in common.iter() {
            let unmoved = arena.equal(named, before);
            let fact = match loop_form_term(arena, f) { Some(__nikaia_value) => __nikaia_value, None => continue };
            found.push((arena.or(vec![unmoved, fact]), loop_flagged_origin()));
        }
    }
    found
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn loop_projected(facts: &[Form], state: &[String], directions: &collections::BTreeMap<String, Form>) -> Vec<Form> {
    let mut gone: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut reading = 0;
    for f in facts.iter() {
        let mut reads = false;
        for (name, _) in f.vars.iter() {
            if nikaia_std::list::contains(&state, &name) || name.contains('~') {
                gone.insert(nikaia_std::block::Text::from(name.to_string()));
                reads = true;
            }
        }
        if reads { reading += 1; }
    }
    let mut now: Vec<Form> = vec![];
    if gone.len() > 2 || reading > 8 {
        for f in facts.iter() {
            let mut reads = false;
            for (name, _) in f.vars.iter() { if gone.contains(name) { reads = true; } }
            if !reads { now.push(f.clone()); }
        }
        return now;
    }
    now = facts.copy_owned();
    for name in gone.iter() {
        let bound = match directions.get(name) { Some(__nikaia_value) => __nikaia_value, None => continue };
        now.push(bound.clone());
    }
    for x in gone.iter() {
        let mut kept: Vec<Form> = vec![];
        let mut ups: Vec<Form> = nikaia_std::block::list(nikaia_std::block::Place::Block);
        let mut downs: Vec<Form> = nikaia_std::block::list(nikaia_std::block::Place::Block);
        for f in now.iter() {
            let cx = nikaia_std::index::or(f.vars.get(x), || 0);
            if cx > 0 { ups.push(f.clone()); } else if cx < 0 { downs.push(f.clone()); } else { kept.push(f.clone()); }
        }
        for u in ups.iter() {
            for d in downs.iter() {
                let cu = nikaia_std::index::or(u.vars.get(x), || 0);
                let cd = match nikaia_std::index::or(d.vars.get(x), || 0).checked_neg() { Some(__nikaia_value) => __nikaia_value, None => continue };
                let a = match scaled(u, cd) { Some(__nikaia_value) => __nikaia_value, None => continue };
                let b = match scaled(d, cu) { Some(__nikaia_value) => __nikaia_value, None => continue };
                let mut joined = match sum(&a, &b, 1) { Some(__nikaia_value) => __nikaia_value, None => continue };
                joined.vars.remove(x);
                kept.push(joined);
            }
        }
        now = kept;
    }
    let mut out: Vec<Form> = vec![];
    for f in now.iter() {
        let mut nothing = true;
        for (_, cx) in f.vars.iter() {
            let cx = nikaia_std::num::value(cx);
            if cx != 0 { nothing = false; }
        }
        if !nothing { out.push(f.clone()); }
    }
    out
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn loop_form_key(f: &Form) -> String {
    let mut parts: Vec<String> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    for (name, cx) in f.vars.iter() {
        let cx = nikaia_std::num::value(cx);
        if cx != 0 { parts.push(format!("{}*{}", cx, name)); }
    }
    parts.push(format!("{}", f.k));
    nikaia_std::block::Text::from(parts.join(" + "))
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn loop_form_term(arena: &mut TermArena, f: &Form) -> Option<i64> {
    let mut left: Option<i64> = None;
    let mut right: Option<i64> = None;
    for (name, cx) in f.vars.iter() {
        let cx = nikaia_std::num::value(cx);
        if cx == 0 { continue; }
        let v = arena.var(name);
        let size = match cx.checked_abs() { Some(__nikaia_value) => __nikaia_value, None => return None };
        let mut part = v;
        if size != 1 {
            let times = arena.int(size);
            part = arena.mul(times, v);
        }
        if cx > 0 { left = Some(if left.is_none() { part } else { arena.add(nikaia_std::index::or(left, || 0), part) }); } else { right = Some(if right.is_none() { part } else { arena.add(nikaia_std::index::or(right, || 0), part) }); }
    }
    if f.k > 0 {
        let k = arena.int(f.k);
        left = Some(if left.is_none() { k } else { arena.add(nikaia_std::index::or(left, || 0), k) });
    } else if f.k < 0 {
        let k = arena.int(match f.k.checked_neg() { Some(__nikaia_value) => __nikaia_value, None => return None });
        right = Some(if right.is_none() { k } else { arena.add(nikaia_std::index::or(right, || 0), k) });
    }
    let l = nikaia_std::index::or(left, || arena.int(0).into());
    let r = nikaia_std::index::or(right, || arena.int(0).into());
    Some(arena.le(l, r))
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn loop_octagons(arena: &mut TermArena, record: &LoopRecord) -> Vec<(i64, String)> {
    let mut found: Vec<(i64, String)> = vec![];
    let origin: &'static str = "octagons";
    let mut names: Vec<String> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    for (name, _) in record.steps.iter() { names.push(nikaia_std::block::Text::from(name.to_string())); }
    for a in 0..names.len() as i64 {
        for b in unsafe { nikaia_std::proven::add::<i64>(a, 1) }..names.len() as i64 {
            let x = nikaia_std::block::Text::from((*unsafe { nikaia_std::proven::read(&names, (a) as usize) }).to_string());
            let y = nikaia_std::block::Text::from((*unsafe { nikaia_std::proven::read(&names, (b) as usize) }).to_string());
            let dx = match *nikaia_std::index::get(&record.steps, &x) { Some(__nikaia_value) => __nikaia_value, None => continue };
            let dy = match *nikaia_std::index::get(&record.steps, &y) { Some(__nikaia_value) => __nikaia_value, None => continue };
            if dx.is_empty() || (dx.len() as i64) != dy.len() as i64 { continue; }
            let mut at_most = true;
            let mut at_least = true;
            let mut x_steady = true;
            let mut y_steady = true;
            for k in 0..dx.len() as i64 {
                if *unsafe { nikaia_std::proven::read(&dx, (k) as usize) } > *unsafe { nikaia_std::proven::read(&dy, (k) as usize) } { at_most = false; }
                if *unsafe { nikaia_std::proven::read(&dx, (k) as usize) } < *unsafe { nikaia_std::proven::read(&dy, (k) as usize) } { at_least = false; }
                if *unsafe { nikaia_std::proven::read(&dx, (k) as usize) } != *unsafe { nikaia_std::proven::read(&dx, (0) as usize) } { x_steady = false; }
                if *unsafe { nikaia_std::proven::read(&dy, (k) as usize) } != *unsafe { nikaia_std::proven::read(&dy, (0) as usize) } { y_steady = false; }
            }
            if x_steady && y_steady || at_most && at_least { continue; }
            let mut left = arena.var(&x);
            let mut right = arena.var(&y);
            let sx = loop_start_of(arena, record, &x);
            let sy = loop_start_of(arena, record, &y);
            if arena.text(sx) != arena.text(sy) {
                left = arena.sub(left, sx);
                right = arena.sub(right, sy);
            }
            if at_most { found.push((arena.le(left, right), nikaia_std::block::Text::from(origin.to_string()))); }
            if at_least { found.push((arena.ge(left, right), nikaia_std::block::Text::from(origin.to_string()))); }
        }
    }
    found
}

